async function randomizeNominationOrder(){if(!adminNominationLeagueId)return toast('Configure and synchronize the auction league first',true);if(!confirm('Randomize every team and restart nominations at the first team?'))return;try{adminNominationState=await api(`/api/auction/nomination-order/randomize?league_id=${encodeURIComponent(adminNominationLeagueId)}`,{method:'POST'});renderAdminNominationOrder();toast('Teams randomized · tracker restarted at the first team')}catch(error){toast(error.message,true)}}
async function resetAuctionAdmin(){if(!adminNominationLeagueId)return toast('Configure and synchronize the auction league first',true);if(prompt('Type RESET to remove every locally recorded auction purchase and turn live mode off.')!=='RESET')return;try{const result=await api(`/api/auction/reset?league_id=${encodeURIComponent(adminNominationLeagueId)}`,{method:'POST'});adminNominationState=result.nomination;renderAdminNominationOrder();toast(`Auction reset · ${result.reset_count} local purchase${result.reset_count===1?'':'s'} removed`)}catch(error){toast(error.message,true)}}
