function clearAuctionPlayerSelection(){document.querySelector('#sale-player-id').value='';document.querySelector('#sale-amount').value='';document.querySelector('#sale-player-match').textContent='Choose a player from the table or type a matching name.';document.querySelectorAll('.auction-player-row').forEach(row=>{const selected=row.dataset.playerId===auctionFocusedPlayerId;row.classList.toggle('selected',selected);row.setAttribute('aria-selected',String(selected))})}
