function auctionTierCliff(focused){const positions=focused?[focused.position]:[...new Set(rankings.map(row=>row.position))];const cliffs=[];positions.forEach(position=>{const rows=rankings.filter(row=>row.position===position&&row.tier!=null).sort((a,b)=>Number(a.overall_rank)-Number(b.overall_rank));if(!rows.length||position==='DEF')return;const tier=Number(rows[0].tier),same=rows.filter(row=>Number(row.tier)===tier),next=rows.find(row=>Number(row.tier)>tier);if(same.length<=3)cliffs.push({position,tier,remaining:same.length,nextTier:next?.tier,players:same.map(row=>row.player_name)})});return cliffs.sort((a,b)=>a.remaining-b.remaining)[0]}
function renderAuctionIntelligence(){const target=document.querySelector('#auction-intelligence-strip');if(!target||!auctionState)return;const intelligence=auctionState.intelligence||{},focused=rankings.find(row=>row.player_id===auctionFocusedPlayerId),run=intelligence.position_runs?.[0],cliff=auctionTierCliff(focused),market=intelligence.market||{},latest=intelligence.latest_purchase;const cards=[focused?['Player focus',focused.player_name,`${focused.position} · rank #${focused.overall_rank??'—'} · Tier ${focused.tier??'—'} · dynamic ${money(focused.dynamic_bid)}`,'good']:['Player focus','Click an available player','The row stays selected while you compare price and opponent pressure.','calm'],run?['Position run',`${run.position} market rush`,run.label,'alert']:['Position run','No active run','No position has taken 3 of the last 6 purchases.','calm'],cliff?['Tier pressure',`${cliff.remaining} ${cliff.position}${cliff.remaining===1?'':'s'} left`,cliff.nextTier?`Tier ${cliff.tier} before Tier ${cliff.nextTier} · ${cliff.players.join(', ')}`:`Last Tier ${cliff.tier} options`,'alert']:['Tier pressure','No immediate cliff',focused?'More than three players remain in this position’s leading tier.':'Focus a player to inspect their tier.','calm'],['Market money',`${money(market.dollars_per_open_slot)} per open spot`,`${money(market.free_money)} above minimum reserves · ${market.open_slots??0} roster spots remain`,Number(market.free_money)>0?'good':'calm'],latest?['Latest winning bid',`${latest.player_name} · ${money(latest.amount)}`,`${latest.franchise_name} added a ${latest.player_position||'player'}`,'calm']:['Latest winning bid','Waiting for a sale','Winning-price context appears after the first purchase.','calm']];target.innerHTML=cards.map(([label,title,copy,tone])=>`<article class="draft-intel-card ${tone}"><span>${escapeHtml(label)}</span><strong>${escapeHtml(title)}</strong><small>${escapeHtml(copy)}</small></article>`).join('')}
function renderAuctionWarRoom(){const war=auctionState?.war_room||{},intelligence=auctionState?.intelligence||{},team=document.querySelector('#auction-war-room-team'),summary=document.querySelector('#auction-war-room-summary'),metrics=document.querySelector('#auction-war-room-metrics'),positions=document.querySelector('#auction-war-room-positions'),byes=document.querySelector('#auction-war-room-byes'),targets=document.querySelector('#auction-war-room-targets'),focused=rankings.find(row=>row.player_id===auctionFocusedPlayerId);if(!team||!summary||!metrics||!positions||!byes||!targets)return;renderOwnerIntelligence('#auction-owner-insights',intelligence.opponent_insights,focused?.position,'auction');if(!war.configured){team.textContent='Select your MFL team';summary.innerHTML='Choose your franchise in <a href="/account">My Account</a> to personalize budget and roster advice.';metrics.innerHTML='';positions.innerHTML='<p class="muted">Roster construction will appear here.</p>';byes.innerHTML='';targets.innerHTML='<p class="muted">Personal auction targets require a selected team.</p>';return}team.textContent=war.franchise_name;summary.textContent=`${war.open_roster_slots} roster spots remain · ${war.open_starter_slots} primary starter slots still open`;metrics.innerHTML=`<article><span>Roster</span><strong>${war.roster_count}/${war.roster_size}</strong><small>${war.open_roster_slots} open spots</small></article><article><span>Budget left</span><strong>${money(war.remaining)}</strong><small>${money(war.spent)} spent</small></article><article><span>Maximum bid</span><strong>${money(war.maximum_bid)}</strong><small>legal ceiling right now</small></article><article><span>Average buy</span><strong>${money(war.average_purchase)}</strong><small>${war.spending_style} through ${war.purchase_count} purchase${war.purchase_count===1?'':'s'}</small></article>`;const allPositions=[...new Set([...Object.keys(war.lineup_requirements||{}),...Object.keys(war.position_counts||{})])];positions.innerHTML=allPositions.map(position=>{const owned=Number(war.position_counts?.[position]||0),required=Number(war.lineup_requirements?.[position]||0),need=Number(war.needs?.[position]||0);return`<span class="war-room-position ${need?'need':'covered'}"><strong>${escapeHtml(position)} ${owned}${required?`/${required}`:''}</strong><small>${need?`Need ${need}`:'Covered'}</small></span>`}).join('')||'<p class="muted">No starting-lineup requirements were synchronized.</p>';byes.innerHTML=(war.bye_warnings||[]).map(row=>`<div class="war-room-bye"><strong>Week ${row.week}: ${row.count} players on bye</strong><span>${escapeHtml(row.players.join(', '))}</span></div>`).join('')||'<p class="war-room-clear">No duplicate bye weeks on the current roster.</p>';const maxBid=Number(war.maximum_bid||0),recommendations=rankings.filter(row=>!row.preference?.do_not_draft&&Number(row.dynamic_bid||row.suggested_auction_value||0)<=maxBid).map(row=>{const need=Number(war.needs?.[row.position]||0),preference=row.preference||{},score=Number(row.overall_rank||99999)-Math.min(need,2)*14-(preference.target?18:0)+(preference.fade?22:0);return{...row,need,score}}).sort((a,b)=>a.score-b.score||Number(a.overall_rank)-Number(b.overall_rank)).slice(0,5);targets.innerHTML=recommendations.map((row,index)=>`<button class="auction-target ${row.player_id===auctionFocusedPlayerId?'selected':''}" onclick='focusAuctionPlayer(${JSON.stringify(row.player_id)})'><span>${index+1}</span><div><strong>${escapeHtml(row.player_name)} · ${escapeHtml(row.position)}</strong><small>${row.need?`Fills ${row.need} open starter slot${row.need===1?'':'s'} · `:''}${money(row.dynamic_bid)} dynamic · max ${money(row.max_recommended_bid)}</small></div></button>`).join('')||'<p class="muted">No ranked player fits under your current maximum bid.</p>'}
function matchSaleFranchise(allowUnique=true){const input=document.querySelector('#sale-franchise-name'),select=document.querySelector('#sale-franchise'),needle=input.value.trim().toLowerCase(),allTeams=auctionState.franchises,openTeams=allTeams.filter(team=>Number(team.slots_remaining)>0),fullExact=allTeams.find(team=>team.name.toLowerCase()===needle&&Number(team.slots_remaining)<=0),exact=openTeams.find(team=>team.name.toLowerCase()===needle),partial=openTeams.filter(team=>team.name.toLowerCase().includes(needle)),match=exact||(allowUnique&&partial.length===1?partial[0]:null);select.value=match?.franchise_id||'';const note=document.querySelector('#sale-franchise-match');note.textContent=match?`Selected: ${match.name}`:fullExact?`${fullExact.name} is finished with a full roster.`:needle?(partial.length?'Keep typing or choose a suggestion.':'No open franchise matches that name.'):'Type a team name or use the list below.';return match}
function syncSaleFranchiseName(){const team=auctionState.franchises.find(item=>item.franchise_id===document.querySelector('#sale-franchise').value);document.querySelector('#sale-franchise-name').value=team?.name||'';document.querySelector('#sale-franchise-match').textContent=team?`Selected: ${team.name}`:'Type a team name or use the list below.'}
function announceAuctionChange(){localStorage.setItem('draftdesk:auction-change',String(Date.now()))}
async function saveSale(event){event.preventDefault();if(document.querySelector('#sale-franchise-name').value.trim())matchSaleFranchise(true);const payload={league_id:AUCTION_LEAGUE_ID,player_id:document.querySelector('#sale-player-id').value,franchise_id:document.querySelector('#sale-franchise').value,amount:document.querySelector('#sale-amount').value,status:'ROSTER'};if(!payload.player_id)return toast('Choose a player first',true);if(!payload.franchise_id)return toast('Choose a franchise or type one matching team name',true);try{await api('/api/auction/purchases',{method:'POST',body:JSON.stringify(payload)});toast(`${document.querySelector('#sale-player-name').value} sold for ${money(payload.amount)}`);event.target.reset();announceAuctionChange();await refreshAuction()}catch(error){toast(error.message,true)}}
function renderInteractiveAuction(){const panel=document.querySelector('#interactive-auction-panel'),room=document.querySelector('#interactive-auction-room'),teamBadge=document.querySelector('#interactive-auction-team'),state=auctionState?.interactive_bidding;if(!panel||!room||!state)return;panel.hidden=!state.enabled;if(!state.enabled)return;teamBadge.textContent=state.current_user_franchise_name||'No MFL team selected';teamBadge.className=`status ${state.current_user_franchise_id?'good':'owned'}`;if(!state.active){const form=state.can_nominate?`<form class="interactive-nomination-form" onsubmit="nominateInteractivePlayer(event)"><label>Nominate a player<input id="interactive-nominee" type="search" list="auction-player-options" autocomplete="off" placeholder="Type an available player name…" required></label><button class="primary" type="submit">Throw player out</button></form>`:`<div class="interactive-waiting"><strong>${escapeHtml(state.is_live?'Waiting for a nomination':'Auction is not live')}</strong><p>${escapeHtml(state.permission_reason||`${state.current_nominator_name||'The current team'} is up next.`)}</p></div>`;room.innerHTML=`<div class="interactive-turn"><span>Currently nominating</span><strong>${escapeHtml(state.current_nominator_name||'Order unavailable')}</strong></div>${form}`;return}const player=state.player||{},photo=player.headshot_url?`<img src="${escapeHtml(player.headshot_url)}" alt="${escapeHtml(player.player_name)} headshot">`:`<div class="interactive-player-placeholder">${escapeHtml(player.position||'NFL')}</div>`,bidForm=state.can_bid?state.current_user_franchise_id===state.high_bid_franchise_id?'<p class="notice success">Your team currently has the high bid.</p>':`<form class="interactive-bid-form" onsubmit="placeInteractiveBid(event)"><label>Your bid<input id="interactive-bid-amount" type="number" min="${escapeHtml(state.minimum_next_bid)}" step="${escapeHtml(state.minimum_bid)}" value="${escapeHtml(state.minimum_next_bid)}" required></label><button class="primary" type="submit">Place bid</button></form>`:`<p class="notice">${escapeHtml(state.permission_reason||'Select your MFL franchise to bid.')}</p>`,adminActions=window.IS_AUCTION_ADMIN?'<div class="toolbar"><button class="primary" onclick="awardInteractiveAuction()">Award winner</button><button onclick="cancelInteractiveNomination()">Cancel nomination</button></div>':'';room.innerHTML=`<div class="interactive-live-grid"><article class="interactive-player-card">${photo}<div><span class="pill">NOW BIDDING</span><h3>${escapeHtml(player.player_name)}</h3><p>${escapeHtml(player.nfl_team||'FA')} · ${escapeHtml(player.position||'—')}</p><small>Nominated by ${escapeHtml(state.nominating_franchise_name||'—')}</small></div></article><article class="interactive-high-bid"><span>High bid</span><strong>${money(state.current_bid)}</strong><p>${escapeHtml(state.high_bid_franchise_name||'No bidder')}</p><small>Next bid: ${money(state.minimum_next_bid)}</small></article><div class="interactive-bid-actions">${bidForm}${adminActions}</div></div><div class="interactive-bid-history"><h3>Bid history</h3><ol>${(state.bids||[]).map(bid=>`<li><strong>${escapeHtml(bid.franchise_name)}</strong><span>${money(bid.amount)}</span></li>`).join('')||'<li>No bids yet.</li>'}</ol></div>`}
async function nominateInteractivePlayer(event){event.preventDefault();const name=document.querySelector('#interactive-nominee').value.trim().toLowerCase(),exact=rankings.find(row=>row.player_name.toLowerCase()===name),partial=rankings.filter(row=>row.player_name.toLowerCase().includes(name)),player=exact||(partial.length===1?partial[0]:null);if(!player)return toast('Type one matching available player name',true);try{await api('/api/auction/interactive/nominate',{method:'POST',body:JSON.stringify({league_id:AUCTION_LEAGUE_ID,player_id:player.player_id})});toast(`${player.player_name} is open for bidding`);await refreshAuction();auctionRevision=auctionState.live.revision}catch(error){toast(error.message,true)}}
async function placeInteractiveBid(event){event.preventDefault();const amount=Number(document.querySelector('#interactive-bid-amount').value);try{await api('/api/auction/interactive/bids',{method:'POST',body:JSON.stringify({league_id:AUCTION_LEAGUE_ID,amount})});toast(`Bid placed at ${money(amount)}`);await refreshAuction();auctionRevision=auctionState.live.revision}catch(error){toast(error.message,true)}}
async function awardInteractiveAuction(){const state=auctionState?.interactive_bidding;if(!state?.active||!confirm(`Award ${state.player.player_name} to ${state.high_bid_franchise_name} for ${money(state.current_bid)}?`))return;try{await api(`/api/admin/interactive-auction/award?league_id=${encodeURIComponent(AUCTION_LEAGUE_ID)}`,{method:'POST'});announceAuctionChange();toast('Winning bid awarded');await refreshAuction();auctionRevision=auctionState.live.revision}catch(error){toast(error.message,true)}}
