function renderLiveDraftBoard(){const state=liveDraftBoardState;if(!state)return;const order=liveDraftBoardOrder(state),completed=order.filter(slot=>slot.completed).length,current=state.current_drafter,currentIndex=current?order.findIndex(slot=>Number(slot.overall_pick)===Number(current.overall_pick)):-1,next=currentIndex>=0?order.slice(currentIndex+1).find(slot=>!slot.completed):null,live=Boolean(state.live?.is_live),status=document.querySelector('#live-board-status');document.querySelector('#live-board-current').textContent=current?.franchise_name||'Draft complete';document.querySelector('#live-board-pick').textContent=current?`#${current.overall_pick} · R${current.round||'—'}.${current.pick||'—'}`:'—';document.querySelector('#live-board-next').textContent=next?.franchise_name||'—';document.querySelector('#live-board-progress').textContent=order.length?`${completed} of ${order.length} picks complete · order updated ${shortDate(state.order_fetched_at)}`:'Waiting for the MFL draft order';status.className=`live-board-badge ${live?'live':'offline'}`;status.textContent=live?'Draft live':'Draft paused';renderTvDraftStage(state);renderTeamDraftBoard(state);renderChronologicalDraftBoard(state)}
